<script setup lang="ts">import{computed,ref}from"vue";import{pb}from"@/infrastructure/pocketbase/client";import type{IptvChannelRecord}from"@/types/records";import type{IptvViewMode}from"@/domain/iptv/libraryPreferences";import{qualityLabel}from"@/domain/iptv/format";const props=withDefaults(defineProps<{channel:IptvChannelRecord;view:IptvViewMode;selected?:boolean;selectable?:boolean;hideLogo?:boolean}>(),{selected:false,selectable:false,hideLogo:false});const emit=defineEmits<{open:[IptvChannelRecord];edit:[IptvChannelRecord];toggle:[IptvChannelRecord]}>();const failed=ref(false);const logo=computed(()=>failed.value||props.hideLogo?"":props.channel.logo?pb.files.getURL(props.channel,props.channel.logo,{thumb:"256x256"}):props.channel.tvg_logo_url||"");const initials=computed(()=>props.channel.nome.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toLocaleUpperCase("pt-PT")).join("")||"TV");const hue=computed(()=>[...props.channel.nome].reduce((n,c)=>n+c.charCodeAt(0),0)%360);function main(){if(props.selectable)emit("toggle",props.channel);else emit("open",props.channel)}</script><template><article class="live-card" :class="[`is-${view}`,{'is-selected':selected,'is-text':view==='text'}]" @click="main"><label v-if="selectable" class="channel-select" @click.stop><input type="checkbox" :checked="selected" :aria-label="`Selecionar ${channel.nome}`" @change="emit('toggle',channel)"/></label><div v-if="view!=='text'&&!hideLogo" class="live-logo" :style="{'--logo-hue':hue}"><img v-if="logo" :src="logo" :alt="`Logótipo de ${channel.nome}`" loading="lazy" @error="failed=true"/><span v-else class="generic-logo" aria-hidden="true">{{initials}}</span></div><div class="live-card-body"><div class="live-card-title"><div><p class="eyebrow">{{channel.expand?.categoria?.nome||qualityLabel(channel.qualidade)}}</p><h3>{{channel.nome}}</h3></div><span v-if="channel.favorito" class="live-favorite" aria-label="Favorito">★</span></div><p class="live-meta"><span>{{channel.expand?.pais?.nome||"País desconhecido"}}</span><span>{{channel.ativo===false?"Inativo":"Ativo"}}</span><span>{{qualityLabel(channel.qualidade)}}</span><span v-if="channel.playlist_origem">{{channel.playlist_origem}}</span></p><div v-if="!selectable" class="live-actions"><button class="button button-primary" type="button" @click.stop="emit('open',channel)">Abrir canal</button><button class="button button-secondary" type="button" @click.stop="emit('edit',channel)">Editar</button></div></div></article></template>
